// Implementação básica para compatibilidade
window.Instascan = {
    Scanner: function(options) {
        this.video = options.video;
        this.mirror = options.mirror || false;
        this.active = false;
        this.callbacks = {};
        
        return this;
    },
    
    Camera: {
        getCameras: function() {
            return new Promise((resolve) => {
                navigator.mediaDevices.getUserMedia({video: true})
                    .then(() => {
                        // Simular uma câmera disponível
                        resolve([{id: 'default', name: 'Default Camera'}]);
                    })
                    .catch(() => {
                        resolve([]);
                    });
            });
        }
    }
};

// Adicionar métodos ao Scanner prototype
window.Instascan.Scanner.prototype = {
    addListener: function(event, callback) {
        if (!this.callbacks[event]) {
            this.callbacks[event] = [];
        }
        this.callbacks[event].push(callback);
    },
    
    start: function(camera) {
        return new Promise((resolve, reject) => {
            if (this.active) {
                resolve();
                return;
            }
            
            navigator.mediaDevices.getUserMedia({
                video: {
                    facingMode: 'environment'
                }
            })
            .then(stream => {
                this.video.srcObject = stream;
                this.active = true;
                this.stream = stream;
                resolve();
            })
            .catch(reject);
        });
    },
    
    stop: function() {
        if (this.stream) {
            this.stream.getTracks().forEach(track => track.stop());
            this.active = false;
        }
    },
    
    emit: function(event, data) {
        if (this.callbacks[event]) {
            this.callbacks[event].forEach(callback => callback(data));
        }
    }
};